在OJ网站上做题时经常出现一种情况，那就是题会做，但是不知道多组输入如何处理，导致无法AC。
本文对ACM模式下C语言和Python的测试用例的输入方式进行了系统的整理。


ACM模式VS核心代码模式
有些企业是在牛客上进行面试，有些企业是在力扣上进行面试，两个平台答题模式是有区别的，所以搞懂不同的输入代码模式是很重要的。
ACM输入模式：在这种模式下，你需要自己构造输入数据格式，把要需要处理的容器填充好，OJ不会给你任何代码，你需要自己导入所需的库，定义数据结构，读取和解析输入数据，然后根据题目要求输出结果，最后也要自己根据题目提示控制返回数据的格式。
#include &lt;iostream&gt;#include &lt;vector&gt;using namespace std;int main() &#123;    int n;    cin &gt;&gt; n;    vector&lt;int&gt; nums(n);    for (int i = 0; i &lt; n; i++) &#123;        cin &gt;&gt; nums[i];    &#125;    // 算法逻辑...    return 0;&#125;
LeetCode 的核心代码模式：在这种模式下，LeetCode 已经为你处理了输入数据，将其封装在了特定的数据结构中（如数组、链表、二叉树等）。你只需要关注如何实现题目要求的算法逻辑，不需要处理输入和输出。这种模式下，你可以更专注于算法本身，但对于数据结构和输入输出的处理则有所限制。
class Solution &#123;public:    int someFunction(vector&lt;int&gt;&amp; nums) &#123;        // 算法逻辑...    &#125;&#125;;
可以看出ACM模式要比核心代码模式多写不少代码，相对来说ACM模式更锻炼代码能力，而核心代码模式是把侧重点完全放在算法逻辑上。
OJ系统中C语言各种输入方式
ACM模式要求写出来的代码是直接可以本地运行的，所以我们需要自己写include哪些库函数，构造输入用例，构造输出用例，因此在OJ网站上做题时经常出现一种情况，那就是题会做，但是不知道多组输入如何处理，导致无法AC。
输入一个数，并原样输出，测试数据有多组：
while(scanf(“%d”,&amp;a)!=EOF)&#123;    printf(“%d\n”,a);&#125;
先输入一个n，后输入一个共n个数的数组,输出这个数组：
scanf(“%d”,&amp;n);for(i=0;i&lt;n;i++)&#123;    scanf(“%d”,&amp;a[i]);&#125;
先输入一个n后输入一个共n个数的数组，最后在跟一个数X，在这n个数中查找x：
scanf(“%d”,&amp;n);for(i=0;i&lt;n;i++)&#123;    scanf(“%d”,&amp;a[i]);&#125;scanf(“%d”,&amp;x);
输入一组数，以0为结束标志：
while(scanf(“%d”,&amp;n),n!=0)
示例1：输入一个数x再原样输出，测试数据有多组，以0为结束标志：
#include&lt;stdio.h&gt;int main()&#123;    int x;    while(scanf(&quot;%d&quot;,&amp;x),x!=0)    &#123;        printf(&quot;%d\n&quot;,x);    &#125;&#125;
示例2：输入一个数组并原样输出，先输入一个n代表数组有n个数，测试数据有多组，以输入的n=0时为结束标志：
#include&lt;stdio.h&gt;int main()&#123;    int n,a[10],i;    while(scanf(&quot;%d&quot;,&amp;n),n!=0)    &#123;        for(i=0;i&lt;n;i++)            scanf(&quot;%d&quot;,&amp;a[i]);	   	for(i=0;i&lt;n;i++)	   	    printf(&quot;%d &quot;,a[i]);	   	printf(&quot;\n&quot;);	&#125;&#125;
二维数组的输入方式：第一行输入一个n，代表接下来输入一个n*n的二维矩阵：
scanf(“%d”,&amp;n);for(i=0;i&lt;n;i++）    for(j=0;j&lt;n;j++)        scanf(“%d”,&amp;a[i][j]);
示例：输入一个二维数组并原样输出，测试数据有多组：

注意：每输入一组数据，按一次回车并输出一组的结果，然后再输入下一组测试数据再按回车再输出下一组的结果。

#include&lt;stdio.h&gt;int main()&#123;    int n,i,j,a[10][10];    while(scanf(&quot;%d&quot;,&amp;n)!=EOF)    &#123;        for(i=0;i&lt;n;i++)            for(j=0;j&lt;n;j++)                scanf(&quot;%d&quot;,&amp;a[i][j]);            for(i=0;i&lt;n;i++)            &#123;                for(j=0;j&lt;n;j++)                &#123;                    printf(&quot;%d&quot;,a[i][j]);                        if(j!=n-1)                            printf(&quot; &quot;);                &#125;                printf(&quot;\n&quot;);            &#125;    &#125;&#125;
末尾加char()
while(scanf(“%c”,&amp;c)!=EOF)&#123;    末尾加getchar(); //按了回车也算是输入了一个字符&#125;
示例：输入一个字符，并判断字符串类型：
#include&lt;stdio.h&gt;int main()&#123;    char c;    while(scanf(&quot;%c&quot;,&amp;c)!=EOF)    &#123;        if(c&gt;=&#x27;a&#x27;&amp;&amp;c&lt;=&#x27;z&#x27;||c&gt;=&#x27;A&#x27;&amp;&amp;c&lt;=&#x27;Z&#x27;)            printf(&quot;alpha\n&quot;);        else if(c&gt;=&#x27;0&#x27;&amp;&amp;c&lt;=&#x27;9&#x27;)            printf(&quot;numeric\n&quot;);        else printf(&quot;other\n&quot;);		    getchar();    &#125;&#125;
字符串中不带空格
while(scanf(“%s”,&amp;str)!=EOF)&#123;&#125;
示例：判断不含空格的字符串是由为回文串：
#include&lt;stdio.h&gt;#include&lt;string.h&gt;int main()&#123;    char s[100];    int x,u,i;    while(scanf(&quot;%s&quot;,s)!=EOF)    &#123;        x=strlen(s);        for(i=0;i&lt;x;i++)        &#123;            if(s[i]!=s[x-1-i])            &#123;                u=0;break;            &#125;            if(s[i]==s[x-1-i])            &#123;                u=1;            &#125;        &#125;        if(u==1)            printf(&quot;Yes\n&quot;);        else if(u==0)            printf(&quot;No\n&quot;);    &#125;&#125;
输入不含空格的字符串数组
for(i=0;i&lt;n;i++)    scanf(&quot;%s&quot;,s[i]);
示例：输入一个n，后面跟n个无空格字符串，（相邻字符串要用空格隔开），输出字符串长度，测试数据有多组：
#include&lt;string.h&gt;#include&lt;stdio.h&gt;int main()&#123;    int n,i,j;    while(scanf(&quot;%d&quot;,&amp;n)!=EOF)    &#123;        int a[20]=&#123;0&#125;;        char s[20][60];        for(i=0;i&lt;n;i++)            scanf(&quot;%s&quot;,s[i]);        for(i=0;i&lt;n;i++)        &#123;            a[i]=strlen(s[i]);        &#125;        for(i=0;i&lt;n;i++)        &#123;            printf(&quot;%s&quot;,s[i]);printf(&quot;%d\n&quot;,a[i]);        &#125;    &#125;&#125;
带空格的字符串
while(gets(str)!=NULL)&#123;&#125;
示例：判断多组含空格的字符串是否为回文串：
#include&lt;stdio.h&gt;#include&lt;string.h&gt;int main()&#123;    char s[100];    int x,u,i;    while(gets(s)!=NULL)    &#123;        x=strlen(s);        for(i=0;i&lt;x;i++)        &#123;            if(s[i]!=s[x-1-i])            &#123;                u=0;break;            &#125;            if(s[i]==s[x-1-i])            &#123;                u=1;            &#125;        &#125;        if(u==1)            printf(&quot;Yes\n&quot;);        else if(u==0)            printf(&quot;No\n&quot;);    &#125;&#125;
输入字符串数组（含空格）
for(i=0;i&lt;n:i++)    gets(s[i]);
示例：计算几行字符串的长度，第一行输入n，下面n行每一行输入一个含空格的字符串：
#include&lt;string.h&gt;#include&lt;stdio.h&gt;int main()&#123;    int n,i,j;    char s[20][60];    while(scanf(&quot;%d&quot;,&amp;n)!=EOF)    &#123;        int a[20]=&#123;0&#125;;        for(i=0;i&lt;n;i++)            gets(s[i]);        for(i=0;i&lt;n;i++)        &#123;            a[i]=strlen(s[i]);        &#125;        for(i=0;i&lt;n;i++)        &#123;            printf(&quot;%d\n&quot;,a[i]);        &#125;    &#125;&#125;
测试数据有T组，先输入一个组数T，接下来每一行第一个数为每组数的个数n，n的后面再跟n个数：
scanf(“%d\n”,&amp;T);while(T--)      //当T减到0跳出循环&#123;    scanf(“%d”,&amp;n);    for(i=0;i&lt;n;i++)        scanf(“%d”,&amp;a[i]);&#125;
示例：输入一个一维数组，并原样输出，先输入一个T，代表有T组测试数据，下面T行每行第一个数n代表每个数组的元素个数：
#include&lt;stdio.h&gt;int main()&#123;    int n,i,a[10],T;    scanf(“%d”,&amp;T);    while(T--)    &#123;        scanf(&quot;%d&quot;,&amp;n);        for(i=0;i&lt;n;i++)            scanf(&quot;%d&quot;,&amp;a[i]);        for(i=0;i&lt;n;i++)            printf(&quot;%d &quot;,a[i]);        printf(&quot;\n&quot;);    &#125;&#125;
OJ系统中Python的多行输入
input()与sys.stdin概述
在线判题系统（Online Judge）的多行输入问题分为定行输入与不定行输入。
若为定行输入，使用循环+input()即可解决。
若为不定行输入，还要看是否有输入结束的标志。
若不定行输入带结束标志，最简单的方法，使用while循环加结束判断语句即可。
若不定行输入不带结束标志，我们应当使用系统输入sys.stdin较为方便，也可使用其他方法。
这里要注意一点，不定行输入不带结束标志问题，在本地IDE上测试时，输入是自己定义的，输入结束你可以疯狂按回车键，如果你通过判断输入是否为空作为跳出循环的判断语句，你的代码可能可以运行正确，但是在OJ里这种判断方法是错误的，是不可取的。
不定行输入有结束标志示例

题目描述 计算a+b
输入描述: 输入包括两个正整数a,b(1 &lt;= a, b &lt;= 10^9),输入数据有多组, 如果输入为0 0则结束输入
输出描述: 输出a+b的结果
示例：
输入
1 5
10 20
0 0
输出
6
30

方法1：sys.stdin
import sysfor line in sys.stdin:    x,y = map(int, line.split())    if x or y:        print(x+y)
方法2：while+input()
注意：使用while循环时，必须加循环结束语句以保证一定能跳出循环，否则OJ不通过。
while True:    x,y = map(int, input().split())    if x == 0 and y == 0:        break    print(x+y)
不定行输入无结束标志示例

题目描述 计算a+b
输入描述: 输入包括两个正整数a,b(1 &lt;= a, b &lt;= 10^9),输入数据有多组, 如果输入为0 0则结束输入
输出描述: 输出a+b的结果
示例：
输入
1 5
10 20
0 0
输出
6
30

方法1：sys.stdin
import sysfor line in sys.stdin:    a,b = map(int, line.split())    print(a+b)
方法2：while+input()
多行输入没有结束标志时，若使用while循环，我们应当使用try，except语句。如下：
while True:    try:        a,b = map(int,input().split())        print(a+b)    except:        break
通过判断输入是否为空作为跳出循环的判断语句，是错误的，如下：
while True:    line = input()    if line == &#x27;&#x27;:        break    else:        a,b = map(int,line.split())        print(a+b)
代码样例
输入为int

输入包括两个正整数a和b，输入数据包含多组。

import sysline = sys.stdin.readlines()for line in lines:    numlist = list(map(int, line.split()))    print(sum(numlist))

输入第一行包括一个数据组数t，接下来每行包括两个正整数a，b，求a+b的结果。

import syslines = sys.stdin.readlines()n = int(lines[0])for i in range(n):    numList = list(map(int, lines[i+1].split()))    print(sum(numList))

输入包括两个正整数a，b，输入数据有多组，如果输入为0，则结束输入。

while True:    a,b = map(int,input().split())    if a== 0 and b == 0:        break    else:        print(a+b)

计算一系列数的和，输入包括多组数据。每组数据一行，每行的第一个整数为整数的个数n，n为0得时候结束输入。接下来的n个正整数，即需要求和的每个正整数。

while True:    a = [int(each) for each in input().split()]    if a[0]==0:        break    print(sum(a[1:]))

计算一系列数的和，输入的第一行包括一个正整数t，表示数据组数。接下来的t行，每行一组数据。每行的第一个整数为整数的个数n，接下来的n个正整数，即需要求和的每个正整数。

n = int(input())for _ in range(n):    numList = list(map(int, input().split()))    print(sum(numList[1:]))

计算一系列数的和，输入数据有多组，每行表示一组输入数据。每行的第一个整数为整数的个数n。接下来的n个正整数，即需要求和的每个正整数。

import syslines = sys.stdin.readlines()for line in lines:    numList = list(map(int, line.split()))    print(sum(numList[1:]))

计算一系列数的和，输入数据有多组，每行表示一组输入数据。每行不定有n个整数，空格隔开。

import sysfor line in sys.stdin:    a  = line.split()    ret = 0    for i in range(len(a)):        ret += int(a[i])    print(ret)
输入为字符串

对输入的字符串进行排序后输出。

while True:    try:        n = input()        strList = list(map(str, input().split()))        strList.sort()        print(&#x27; &#x27;.joint(strList))    except:        break

对输入的字符串进行排序后输出。多个测试用例，每个测试用例一行。每行用空格隔开，有n个字符。

while True:    try:        arr = list(map(str, input().split()))        arr.sort()        print(&#x27; &#x27;.join(arr))    except:        break

对输入的字符串进行排序后输出。多个测试用例，每个测试用例一行。每行通过，隔开，有n个字符。

while True:    try:        a = input().split(&quot;,&quot;)        a.sort()        print(&quot;,&quot;.join(a))    except:        break
其他问题

输入一个字符串，拆分成单个字符的列表。

import sysstr_input = sys.stdin.readline().split()strList = [i for i in str_input[0]]print(strList)

第一行表示接下来要输入几组数据

count = list(map(int, input().split()))queue = []for _ in range(count[0]):    queue.append(list(map(int, input().split())))

在项目中使用 GTest 编写单测以保证代码质量是必要的，通过构造各种单元测试的case，可以测试功能是否正确，发现肉眼不容易发现的bug。
GTest
是 Google 发布的一款非常优秀的开源 C/C++ 单元测试框架，它简单易用，功能完善，已被应用于多个开源项目及Google内部项目中：ChromeWeb浏览器、LLVM编译器、ProtocolBuffers数据交换格式等。
本文分享 GTest 的核心用法、常用技巧以及单测编写的思路，包含最必要、最常用的内容，能覆盖大部分场景的单测需求，同时会引用外部文档供扩展阅读。



安装
官方传送门：GoogleTest - Google Testing and Mocking Framework
现在官方已经把 GoogleTest 和 GoogleMock 一起维护，所以这个 git 仓库还包含了 GoogleMock。
GitHub 源码仓库安装
➜  ~ wget https://github.com/google/googletest/archive/refs/tags/v1.14.0.tar.gz➜  ~ tar xf v1.14.0.tar.gz➜  ~ cd googletest-1.14.0➜  googletest-1.14.0 cmake -DBUILD_SHARED_LIBS=ON .➜  googletest-1.14.0 make➜  googletest-1.14.0 sudo cp -a googletest/include /usr/include➜  googletest-1.14.0 sudo cp -a lib/libgtest_main.so lib/libgtest.so /usr/lib/
这样就 OK 了，可以用 sudo ldconfig -v | grep gtest 检查，看到下面就 OK 了：
libgtest.so -&gt; libgtest.solibgtest_main.so -&gt; libgtest_main.so
Ubuntu apt 源码安装
➜  ~ sudo apt-get install libgtest-dev➜  ~ cd /usr/src/gtest➜  gtest sudo cmake CMakeLists.txt➜  gtest sudo make➜  gtest sudo cp *.a /usr/lib
上述步骤OK后就可以使用-lgtest选项编译测试代码了。
概念
Test Suite
TEST(TestSuiteName, TestCaseName) &#123;    // 单测代码    EXPECT_EQ(func(0), 0);&#125;

TestSuiteName 用来汇总 test case，相关的 test case 应该是相同的
TestSuiteName。一个文件里只能有一个 TestSuiteName，建议命名为这个文件测试的类名。
TestCaseName
是测试用例的名称。建议有意义，比如“被测试的函数名称”，或者被测试的函数名的不同输入的情况。
TestSuiteName_TestCaseName 的组合应该是唯一的。
GTest 生成的类名是带下划线的，所以上面这些名字里不建议有下划线。

Test Case
一个 TEST(Foo, Bar){...} 就是一个 Test Case。考虑到构造输入有成本，通常一个
TEST(Foo, Bar)
里会反复修改输入，构造多个 case，测试不同的执行流程。这里建议用大括号分隔不同的 case，整体更条理。另一个好处在于：每个变量的生命周期仅限于大括号内。这样就可以反复使用相同的变量名，而不用给变量名编号。
TEST(Foo, bar) &#123;    // case 1: enable = true    &#123;        Context ctx;        params.enable_refresh = true;        ASSERT_EQ(ctx-&gt;is_enable_fresh(), true);    &#125;    // case 2: enable = false    &#123;        Context ctx;        params.enable_refresh = false;        ASSERT_EQ(ctx-&gt;is_enable_fresh(), false);    &#125;&#125;
如果待测函数十分复杂，建议拆分多个 TEST(Foo, Bar){...}，避免 Test
Case 代码膨胀。比如：
// 待测函数int foo(TarAddr ta) &#123;    if (!ta)        return -1;    switch(ta.did) &#123;        case 0x193b:            ...        case 0x1204:            ...    &#125;&#125;TEST(Foo, IsNil) &#123;    ...&#125;TEST(Foo, 0x193b) &#123;    ...&#125;TEST(Foo, 0x1204) &#123;    ...&#125;
使用
官方 WIKI：GTest
断言
GTest 使用一系列断言的宏来检查返回值是否符合预期、是否抛出预期的异常等。主要分为两类：ASSERT
和
EXPECT。区别在于 ASSERT 不通过的时候会认为是一个 fatal 的错误，退出当前函数（只是函数）。而 EXPECT 失败的话会继续运行当前函数，所以对于函数内几个失败可以同时报告出来。
通常我们用 EXPECT 级别的断言就好，除非你认为当前检查点失败后函数的后续检查没有意义:

如果某个判断不通过时，会影响后续步骤，要使用 ASSERT。常见的是空指针，或者数组访问越界。
其他情况，可以使用 EXPECT，尽可能多测试几个用例。

基础的断言



Fatal assertion
Nonfatal assertion
Verifies




ASSERT_TRUE(_condition_);
EXPECT_TRUE(_condition_);
condition is true


ASSERT_FALSE(_condition_);
EXPECT_FALSE(_condition_);
condition is false



数值比较



Fatal assertion
Nonfatal assertion
Verifies




ASSERT_EQ(_val1_, _val2_);
EXPECT_EQ(_val1_, _val2_);
val1 == val2


ASSERT_NE(_val1_, _val2_);
EXPECT_NE(_val1_, _val2_);
val1 != val2


ASSERT_LT(_val1_, _val2_);
EXPECT_LT(_val1_, _val2_);
val1 &lt; val2


ASSERT_LE(_val1_, _val2_);
EXPECT_LE(_val1_, _val2_);
val1 &lt;= val2


ASSERT_GT(_val1_, _val2_);
EXPECT_GT(_val1_, _val2_);
val1 &gt; val2


ASSERT_GE(_val1_, _val2_);
EXPECT_GE(_val1_, _val2_);
val1 &gt;= val2



浮点数比较



Fatal assertion
Nonfatal assertion
Verifies




ASSERT_FLOAT_EQ(_val1_, _val2_);
EXPECT_FLOAT_EQ(_val1_, _val2_);
val1 == val2 (within 4 ULPs)


ASSERT_DOUBLE_EQ(_val1_, _val2_);
EXPECT_DOUBLE_EQ(_val1_, _val2_);
val1 == val2 (within 4 ULPs)


ASSERT_NEAR(_val1_, _val2_, _abs_error_);
EXPECT_NEAR(_val1_, _val2_, _abs_error_);
判断两个数字的绝对值相差是否小于等于 abs_error



字符串比较



Fatal assertion
Nonfatal assertion
Verifies




ASSERT_STREQ(_str1_, _str2_);
EXPECT_STREQ(_str1_, _str_2);
the two C strings have the same content


ASSERT_STRNE(_str1_, _str2_);
EXPECT_STRNE(_str1_, _str2_);
the two C strings have different content


ASSERT_STRCASEEQ(_str1_, _str2_);
EXPECT_STRCASEEQ(_str1_, _str2_);
the two C strings have the same content, ignoring case


ASSERT_STRCASENE(_str1_, _str2_);
EXPECT_STRCASENE(_str1_, _str2_);
